WFJ.Data.add("book", {
  ["220af383b60d9222"] = { "だが、それらの疑問に答えるには、ペンダントについてさらなる研究と実験を行わねばならない。そして、Lordamere Interment Campでは、その任務に必要な人手も設備も揃えられないのではないかと危惧している。そこで私は、以前の私のような苛立ちを避けられるよう、試験方法について具体的な指示を添えて、血石のペンダントを伝令に託してDalaranへ送った。", "." },
  ["225dd37063ed40ed"] = { "この遠征のために、私はAjeck RouackとSir S. J Erlgadin、そして信頼する従者のBarnil Stonepotを集めた。私はAjeckの父の側で、Allianceを守る多くの戦いを共に戦った。彼女が成長した姿を見るのは実に感慨深い。彼女の父は武器の扱いを彼女にしっかりと仕込んだ。その弓の腕前を見ると、あの血管にはエルフの血が流れているのではないかと思えてくる。", "." },
  ["22ac9901db7788a2"] = { "この手紙は、私が作り得る最も強力なインクで書いている、{name}。お前以外にこれを読もうとする者がいれば、たちまち呪われるだろう。私にはそれほどの力がある。私は意のままにTwisting Netherから悪魔を召喚する。眠っている敵も、戦場の敵も、等しく苦しめる。そして今、お前もまた我が道の力を目にした。我が兄弟たちはそれを喜んでいる。\n\nこの地に慣れたら、Denの奥底で私を探せ。重要な事柄について話がある。\n\n-ウォーロックのトレーナー、Nartok", "." },
  ["22cbd1719323b4c4"] = { "--17日目\nUlegが任務から戻った。彼は失敗し、Thargilは捕らえられた。私はUlegに、この報告をNazeerへ届けさせた。\n\n私はここに残る。Theramore沖で船の動きが増えているのを確認した。引き続き監視を行い、注目すべき出来事があれば自ら報告する。", "." },
  ["22dd9cc0b18cd88c"] = { "JARIENとSOTHOS(続き)……\n\nこうして彼らは、Crusadeに加わろうとする者に課される試練に臨むことになった。とりわけ彼らが望んだのは、その隊列における騎士の地位だった。どうやらそれには、より厳しい試験が必要だったらしい。後に分かったことだが、Sothosは最後の試験に落ちていたのだ。しかしJarienはそれを受け入れず、公然と逆らって、彼も自分と共に騎士の列に加えるよう言い張った。我々が集めた情報によれば、Grand Crusader Dathrohanは自らの部屋の真ん中で、その場で二人とも斬り殺したという。\n\nかくして、これら呪われた場所のもう一つは、StratholmeのThe Scarlet Bastion内にあるThe Crimson Throneである。", "." },
  ["22df0d19bb53a01b"] = { "祠に隠された宝石が見つからなければ、murlocの1体が持っているのかもしれない。\n\n柄の部分\n杖のこの部分は、今Felwoodと呼ばれている地の近くでtreantたちに託された。furbolgも我らの種族も、あれほど壮麗な生き物が、この地を覆った堕落に屈することがあるなどとは思いもしなかった。\n\n調べたところでは、守護者たちはその部品を小さな空き地で、鍵のかかった箱にしまっておいたらしい。それ以上を知るには、Shael'drynと話さなければならない。", "." },
})
